const message = $input.first().json.message;
const text = message?.text?.toLowerCase() || '';
const chatId = message?.chat?.id;

// Określ kontekst wiadomości
let context = 'unknown';

// Sprawdź czy to odpowiedź na podsumowanie dnia
if (text.includes(',') || 
    text.includes('nic') || 
    text.includes('wszystko') ||
    text.includes('done') ||
    text.includes('zrobione')) {
  context = 'daily_summary';
}

// Sprawdź czy to odpowiedź tak/nie (przesunięcie tasków)
if (text === 'tak' || text === 'nie' || text === 't' || text === 'n' || text === 'yes' || text === 'no') {
  context = 'postpone_response';
}

// Komendy specjalne
if (text.startsWith('/')) {
  if (text === '/status' || text === '/stats') context = 'command_status';
  if (text === '/plan' || text === '/today') context = 'command_plan';
  if (text === '/help') context = 'command_help';
}

return [{
  json: {
    context: context,
    text: message?.text || '',
    chatId: chatId,
    messageId: message?.message_id,
    userId: message?.from?.id,
    timestamp: Date.now()
  }
}];

const inputData = $('Check Context').first().json;
const userResponse = inputData.text;
const tasksData = $input.first().json;

// Znajdź dzisiejszy task
const today = new Date().toISOString().split('T')[0];
const tasks = tasksData.tasks || [];
let todayTask = tasks.find(t => t.name.includes(today)) || tasks[0];

if (!todayTask) {
  return [{
    json: {
      error: true,
      summary: '❌ Nie znaleziono dzisiejszego Daily Task.',
      chatId: inputData.chatId,
      completed: [],
      incomplete: []
    }
  }];
}

// POBIERZ MAPOWANIE Z DESCRIPTION
let taskMapping = [];
const desc = todayTask.description || '';
const mappingMatch = desc.match(/<!-- TASK_MAPPING_JSON\n(.+?)\nEND_TASK_MAPPING -->/s);
if (mappingMatch) {
  try {
    taskMapping = JSON.parse(mappingMatch[1]);
  } catch (e) {
    taskMapping = [];
  }
}

// Pobierz wszystkie itemy z checklisty (z numerami)
const checklists = todayTask.checklists || [];
let allItems = [];
let checklistId = null;
let itemIndex = 1;

for (const checklist of checklists) {
  checklistId = checklist.id;
  for (const item of checklist.items || []) {
    if (item.name.includes('───')) continue; // Separator

    // Znajdź mapowanie dla tego itema
    const mapping = taskMapping.find(m => m.name === item.name) || {};

    allItems.push({
      index: itemIndex,
      id: item.id,
      name: item.name,
      resolved: item.resolved || false,
      checklistId: checklist.id,
      // Mapowanie do oryginalnego taska
      originalTaskId: mapping.originalTaskId || null,
      originalListId: mapping.originalListId || null,
      isHabit: mapping.isHabit || false
    });
    itemIndex++;
  }
}

if (allItems.length === 0) {
  return [{
    json: {
      error: true,
      summary: '❌ Brak itemów w checkliście.',
      chatId: inputData.chatId,
      completed: [],
      incomplete: []
    }
  }];
}

// Parsuj odpowiedź użytkownika
const userText = userResponse.trim();

// Sprawdź czy to numery (np. "1,3,5" lub "1, 3, 5")
const numberPattern = /^[\d,\s]+$/;
const isNumbers = numberPattern.test(userText);

const completed = [];
const incomplete = [];

if (userText.toLowerCase() === 'wszystko' || userText.toLowerCase() === 'all') {
  completed.push(...allItems.filter(i => !i.resolved));
  incomplete.push(...allItems.filter(i => i.resolved));
} else if (userText.toLowerCase() === 'nic' || userText === '0') {
  incomplete.push(...allItems);
} else if (isNumbers) {
  const selectedNumbers = userText.split(',').map(n => parseInt(n.trim())).filter(n => !isNaN(n));

  for (const item of allItems) {
    if (selectedNumbers.includes(item.index)) {
      completed.push(item);
    } else {
      incomplete.push(item);
    }
  }
} else {
  const userItems = userText.toLowerCase().split(',').map(s => s.trim()).filter(s => s.length > 0);

  for (const item of allItems) {
    const itemLower = item.name.toLowerCase();
    const itemClean = itemLower.replace(/^[\u{1F300}-\u{1F9FF}\s]+/u, '').trim();

    const matched = userItems.some(userItem => {
      if (userItem.length < 3) return false;
      if (itemLower === userItem || itemClean === userItem) return true;
      if (userItem.length >= 5 && (itemLower.includes(userItem) || itemClean.includes(userItem))) return true;
      return false;
    });

    if (matched) {
      completed.push(item);
    } else {
      incomplete.push(item);
    }
  }
}

// Przygotuj podsumowanie z numerami
let summary = '📋 *Lista zadań:*\n';
for (const item of allItems) {
  const isDone = completed.some(c => c.id === item.id);
  const mark = isDone ? '✅' : '⬜';
  summary += `${mark} ${item.index}. ${item.name}\n`;
}

summary += '\n';

if (completed.length > 0) {
  summary += `✅ Zaznaczono: ${completed.length} zadań\n`;
}

if (incomplete.length > 0 && completed.length > 0) {
  summary += `⬜ Pozostało: ${incomplete.length} zadań\n`;
}

const allDone = incomplete.length === 0 && completed.length > 0;

if (allDone) {
  summary += '\n🔥 *Wszystko zrobione! Streak +1!* 🎉';
} else if (completed.length === 0) {
  summary += '\n💡 Wpisz numery wykonanych zadań, np: *1, 3, 5*\n';
  summary += 'lub: *wszystko* / *nic*';
}

return [{
  json: {
    error: false,
    taskId: todayTask.id,
    checklistId: checklistId,
    completed: completed,
    incomplete: incomplete,
    allDone: allDone,
    summary: summary,
    chatId: inputData.chatId
  }
}];

const data = $input.first().json;

if (data.error || !data.completed || data.completed.length === 0) {
  return [{
    json: {
      skip: true,
      ...data
    }
  }];
}

// Zwróć każdy completed item jako osobny output
const items = data.completed.map(item => ({
  json: {
    itemId: item.id,
    checklistId: item.checklistId,
    itemName: item.name,
    // Mapowanie do oryginalnego taska
    originalTaskId: item.originalTaskId,
    originalListId: item.originalListId,
    isHabit: item.isHabit,
    originalData: data
  }
}));

return items;

const inputData = $('Check Context').first().json;
const response = inputData.text.toLowerCase();

let message = '';

if (response === 'tak' || response === 't' || response === 'yes') {
  message = '✅ *Przesunięte na jutro!*\n\nMiłych snów! 😴\nJutro nowy dzień, nowy streak! 💪';
} else {
  message = 'OK, zostawiam bez zmian.\n\nMiłych snów! 😴';
}

return [{
  json: {
    message: message,
    chatId: inputData.chatId
  }
}];

const task = $input.first().json;
const chatId = $('Check Context').first().json.chatId;

let currentStreak = 0;
let bestStreak = 0;
let totalDays = 0;
let totalXP = 0;

for (const field of task.custom_fields || []) {
  if (field.name === 'Current Streak') currentStreak = parseInt(field.value) || 0;
  if (field.name === 'Best Streak') bestStreak = parseInt(field.value) || 0;
  if (field.name === 'Total Days Completed') totalDays = parseInt(field.value) || 0;
  if (field.name === 'Total XP') totalXP = parseInt(field.value) || 0;
}

// Oblicz level
const levelThresholds = [
  {level: 1, xp: 0, title: 'Nowicjusz'},
  {level: 2, xp: 100, title: 'Początkujący'},
  {level: 3, xp: 250, title: 'Adept'},
  {level: 4, xp: 500, title: 'Praktyk'},
  {level: 5, xp: 1000, title: 'Skupiony'},
  {level: 7, xp: 2000, title: 'Weteran'},
  {level: 10, xp: 3500, title: 'Ekspert'},
  {level: 15, xp: 6000, title: 'Mistrz'},
  {level: 20, xp: 10000, title: 'Legenda'},
  {level: 25, xp: 15000, title: 'ADHD Conqueror'}
];

let currentLevel = levelThresholds[0];
let nextLevel = levelThresholds[1];
for (let i = 0; i < levelThresholds.length; i++) {
  if (totalXP >= levelThresholds[i].xp) {
    currentLevel = levelThresholds[i];
    nextLevel = levelThresholds[i + 1] || null;
  }
}

// Streak bonus info
let streakBonusInfo = '+0 XP/dzień';
if (currentStreak >= 31) streakBonusInfo = '+20 XP/dzień 💎';
else if (currentStreak >= 15) streakBonusInfo = '+15 XP/dzień 🔥';
else if (currentStreak >= 8) streakBonusInfo = '+10 XP/dzień 🔥';
else if (currentStreak >= 4) streakBonusInfo = '+5 XP/dzień';

let message = '📊 *PLAYER STATS*\n';
message += '━━━━━━━━━━━━━━━━\n\n';

message += `🎮 *Level ${currentLevel.level}:* ${currentLevel.title}\n`;
if (nextLevel) {
  const xpToNext = nextLevel.xp - totalXP;
  message += `   Next: ${nextLevel.title} (${xpToNext} XP)\n`;
}
message += '\n';

message += `⭐ *Total XP:* ${totalXP.toLocaleString()}\n`;
message += `📅 *Days Completed:* ${totalDays}\n\n`;

message += `🔥 *Current Streak:* ${currentStreak} dni\n`;
message += `   Bonus: ${streakBonusInfo}\n`;
message += `🏆 *Best Streak:* ${bestStreak} dni\n\n`;

// Następne milestone'y
message += '🎯 *Next Goals:*\n';
if (currentStreak < 7) message += `   🔥 Fire Starter: ${7 - currentStreak} dni\n`;
else if (currentStreak < 14) message += `   🔥🔥 Inferno: ${14 - currentStreak} dni\n`;
else if (currentStreak < 30) message += `   👑 Eternal Flame: ${30 - currentStreak} dni\n`;
else if (currentStreak < 60) message += `   💎 Unstoppable: ${60 - currentStreak} dni\n`;

const xpMilestones = [100, 500, 1000, 2500, 5000, 10000];
for (const milestone of xpMilestones) {
  if (totalXP < milestone) {
    message += `   ⭐ ${milestone} XP: ${milestone - totalXP} XP\n`;
    break;
  }
}

return [{
  json: {
    message: message,
    chatId: chatId
  }
}];

// Zbierz wszystkie wyniki i przekazuj oryginalne dane
const items = $input.all();
const firstItem = items[0]?.json?.originalData || $('Process Summary').first().json;

return [{
  json: firstItem
}];

const processData = $('Process Summary').first().json;
const playerStats = $input.first().json;

// Pobierz aktualne statystyki
let currentStreak = 0;
let bestStreak = 0;
let totalXP = 0;
let totalDays = 0;

for (const field of playerStats.custom_fields || []) {
  if (field.name === 'Current Streak') currentStreak = parseInt(field.value) || 0;
  if (field.name === 'Best Streak') bestStreak = parseInt(field.value) || 0;
  if (field.name === 'Total XP') totalXP = parseInt(field.value) || 0;
  if (field.name === 'Total Days Completed') totalDays = parseInt(field.value) || 0;
}

const completedCount = processData.completed?.length || 0;
const allDone = processData.allDone || false;

// === OBLICZANIE XP ===

// 1. Base XP: 5 XP per completed task
const baseXP = completedCount * 5;

// 2. Bonus za complete day: +20 XP
const completeDayBonus = allDone ? 20 : 0;

// 3. Streak bonus (dzienny)
let streakBonus = 0;
if (allDone) {
  const newStreak = currentStreak + 1;
  if (newStreak >= 31) streakBonus = 20;
  else if (newStreak >= 15) streakBonus = 15;
  else if (newStreak >= 8) streakBonus = 10;
  else if (newStreak >= 4) streakBonus = 5;
}

// Suma earned XP
const earnedXP = baseXP + completeDayBonus + streakBonus;

// === OBLICZANIE STREAK ===
let newStreak = allDone ? currentStreak + 1 : 0;
let newBestStreak = Math.max(bestStreak, newStreak);
let newTotalDays = allDone ? totalDays + 1 : totalDays;
let newTotalXP = totalXP + earnedXP;

// === SPRAWDZANIE ACHIEVEMENTÓW ===
const unlockedAchievements = [];

// Streak achievements
if (newStreak === 7) unlockedAchievements.push({name: '🔥 Fire Starter', xp: 50});
if (newStreak === 14) unlockedAchievements.push({name: '🔥🔥 Inferno', xp: 100});
if (newStreak === 30) unlockedAchievements.push({name: '👑 Eternal Flame', xp: 250});
if (newStreak === 60) unlockedAchievements.push({name: '💎 Unstoppable', xp: 500});

// XP milestones
if (totalXP < 100 && newTotalXP >= 100) unlockedAchievements.push({name: '⭐ First Steps', xp: 10});
if (totalXP < 500 && newTotalXP >= 500) unlockedAchievements.push({name: '⭐⭐ Getting Serious', xp: 25, reward: '☕ Kawa Speciality'});
if (totalXP < 1000 && newTotalXP >= 1000) unlockedAchievements.push({name: '⭐⭐⭐ XP Collector', xp: 50, reward: '🍫 Słodycze Premium'});
if (totalXP < 2500 && newTotalXP >= 2500) unlockedAchievements.push({name: '🌟 Dedicated', xp: 100, reward: '🎧 Gadget'});
if (totalXP < 5000 && newTotalXP >= 5000) unlockedAchievements.push({name: '🌟🌟 Veteran', xp: 150, reward: '📦 Item'});
if (totalXP < 10000 && newTotalXP >= 10000) unlockedAchievements.push({name: '💫 Legend', xp: 300, reward: '🎁 MEGA'});

// Dodaj XP za achievements
let achievementXP = 0;
for (const ach of unlockedAchievements) {
  achievementXP += ach.xp;
}
newTotalXP += achievementXP;

// === OBLICZANIE LEVELU ===
const levelThresholds = [
  {level: 1, xp: 0, title: 'Nowicjusz'},
  {level: 2, xp: 100, title: 'Początkujący'},
  {level: 3, xp: 250, title: 'Adept'},
  {level: 4, xp: 500, title: 'Praktyk'},
  {level: 5, xp: 1000, title: 'Skupiony'},
  {level: 7, xp: 2000, title: 'Weteran'},
  {level: 10, xp: 3500, title: 'Ekspert'},
  {level: 15, xp: 6000, title: 'Mistrz'},
  {level: 20, xp: 10000, title: 'Legenda'},
  {level: 25, xp: 15000, title: 'ADHD Conqueror'}
];

let currentLevel = levelThresholds[0];
for (const threshold of levelThresholds) {
  if (newTotalXP >= threshold.xp) currentLevel = threshold;
}

// === BUDOWANIE SUMMARY ===
let summary = processData.summary + '\n\n';
summary += '━━━━━━━━━━━━━━━━\n';
summary += '💰 *XP Earned:*\n';
summary += `   Tasks: +${baseXP} XP\n`;
if (completeDayBonus > 0) summary += `   Complete Day: +${completeDayBonus} XP\n`;
if (streakBonus > 0) summary += `   Streak Bonus: +${streakBonus} XP\n`;
if (achievementXP > 0) summary += `   Achievements: +${achievementXP} XP\n`;
summary += `   *Total: +${earnedXP + achievementXP} XP*\n\n`;

if (unlockedAchievements.length > 0) {
  summary += '🏆 *UNLOCKED:*\n';
  for (const ach of unlockedAchievements) {
    summary += `   ${ach.name}!\n`;
    if (ach.reward) summary += `   🎁 Reward: ${ach.reward}\n`;
  }
  summary += '\n';
}

summary += `🔥 Streak: ${newStreak} dni\n`;
summary += `⭐ Total XP: ${newTotalXP}\n`;
summary += `📊 Level ${currentLevel.level}: ${currentLevel.title}`;

return [{
  json: {
    ...processData,
    // XP data
    earnedXP: earnedXP + achievementXP,
    baseXP,
    completeDayBonus,
    streakBonus,
    achievementXP,
    // New stats
    newStreak,
    newBestStreak,
    newTotalXP,
    newTotalDays,
    // Level
    currentLevel: currentLevel.level,
    levelTitle: currentLevel.title,
    // Achievements
    unlockedAchievements,
    // Summary
    xpSummary: summary
  }
}];

// Pobierz dane z Calculate XP
const xpData = $('Calculate XP').first().json;
const taskId = $('Process Summary').first().json.taskId;
const chatId = $('Check Context').first().json.chatId;

// Player Stats Task ID
const playerStatsId = '86c7ec2db';

// Przygotuj listę aktualizacji do wykonania przez HTTP Request
const updates = [
  // Player Stats
  { taskId: playerStatsId, fieldId: 'ae4e0c86-eacc-426a-a76a-1a3e1a65db12', value: xpData.newStreak, name: 'Current Streak' },
  { taskId: playerStatsId, fieldId: '3bf835b6-0323-4930-9cf0-3e33a8a98829', value: xpData.newBestStreak, name: 'Best Streak' },
  { taskId: playerStatsId, fieldId: 'a6e04afa-5257-493e-8704-6bf27b79dcdf', value: xpData.newTotalXP, name: 'Total XP' },
  { taskId: playerStatsId, fieldId: '92dd47d6-c58c-4c42-b739-673a87db9470', value: xpData.newTotalDays, name: 'Total Days' },
  { taskId: playerStatsId, fieldId: '52c699be-429c-4878-a818-415ca331175c', value: Date.now(), name: 'Last Active' },
  // Daily Task
  { taskId: taskId, fieldId: '8896c9a2-87f8-4221-bf52-e38ce246f24b', value: xpData.earnedXP, name: 'XP Earned Today' },
  { taskId: taskId, fieldId: '87050fe6-ddb6-452a-8bc0-95a2f6c045b9', value: xpData.newStreak, name: 'Streak Days' }
];

// Zwróć jako osobne itemy dla Split In Batches
return updates.map(u => ({
  json: {
    ...u,
    xpSummary: xpData.xpSummary,
    chatId: chatId
  }
}));
